opt_sum.source:
#include <stdint.h>
/* Sum an array: watch loop structure, unrolling and register use change by -O level. */
int32_t sum_array(const int32_t *a, int n)
{
    int32_t s = 0;
    for (int i = 0; i < n; i++)
        s += a[i];
    return s;
}

opt_flag.source:
#include <stdint.h>
/* Set by an interrupt handler. Missing volatile => optimizer may hoist the load out of the loop. */
uint32_t g_ready;
volatile uint32_t g_ready_v;

void wait_ready(void)
{
    while (g_ready == 0) { }
}

void wait_ready_volatile(void)
{
    while (g_ready_v == 0) { }
}

opt_clear.source:
#include <stdint.h>
/* A hand-written clear loop: GCC may recognize the idiom and call memset. */
void clear_buf(uint8_t *p, unsigned n)
{
    for (unsigned i = 0; i < n; i++)
        p[i] = 0;
}

opt_inline.source:
#include <stdint.h>
/* Small helper + constant arguments: inlining and constant folding. */
static int32_t scale(int32_t x, int32_t k) { return (x * k) >> 4; }

int32_t calc(void)
{
    return scale(100, 8) + scale(20, 16);
}

int32_t calc_var(int32_t x)
{
    return scale(x, 8) + scale(x, 16);
}

opt_switch.source:
#include <stdint.h>
/* Dense switch: compiler may emit a jump table, a lookup table, or compare chains. */
int map_cmd(int c)
{
    switch (c) {
    case 0: return 11;
    case 1: return 29;
    case 2: return 37;
    case 3: return 41;
    case 4: return 53;
    case 5: return 67;
    default: return -1;
    }
}

sections.source:
#include <stdint.h>
/* Where does each object end up? (inspected with arm-none-eabi-nm -S and size -A) */
int32_t        g_init       = 42;          /* initialized global      */
int32_t        g_zero;                     /* zero-initialized global */
int32_t        g_zero_expl  = 0;           /* explicitly zero         */
const int32_t  g_const      = 7;           /* const global            */
const uint8_t  g_table[256] = { 1, 2, 3 }; /* large const table       */
static int32_t s_file_static = 5;          /* file-scope static       */
const char    *g_msg        = "hello";     /* pointer (RW) to literal */
char           g_buf[64];                  /* uninitialized array     */
__attribute__((section(".noinit"))) uint32_t g_reset_reason;

int32_t counter(void)
{
    static int32_t calls;                  /* static local (zero)     */
    static int32_t base = 100;             /* static local (init)     */
    int32_t local = base + calls++;        /* automatic: stack/reg    */
    return local + s_file_static + g_table[3] + g_const;
}

void unused_function(void) { g_buf[0] = 1; }

int main(void)
{
    g_zero = counter() + g_init + g_zero_expl + g_msg[0] + (int32_t)g_reset_reason;
    for (;;) { }
}

void Reset_Handler(void) { main(); }

sections.linkerScript:
MEMORY
{
  FLASH (rx)  : ORIGIN = 0x08000000, LENGTH = 512K
  RAM   (rwx) : ORIGIN = 0x20000000, LENGTH = 128K
}
ENTRY(Reset_Handler)
SECTIONS
{
  .text : { KEEP(*(.isr_vector)) *(.text*) } > FLASH
  .rodata : { *(.rodata*) } > FLASH
  _sidata = LOADADDR(.data);
  .data : { _sdata = .; *(.data*) _edata = .; } > RAM AT > FLASH
  .bss (NOLOAD) : { _sbss = .; *(.bss*) *(COMMON) _ebss = .; } > RAM
  .noinit (NOLOAD) : { *(.noinit*) } > RAM
  /DISCARD/ : { *(.ARM.exidx*) *(.comment) }
}

walkthrough.source:
#include <stdint.h>
/* Small functions compiled for Cortex-M0 (Thumb-1) for the step-by-step walkthrough. */
int sum_n(int n)
{
    int s = 0;
    for (int i = 1; i <= n; i++)
        s += i;
    return s;
}

int max3(int a, int b, int c)
{
    int m = a;
    if (b > m) m = b;
    if (c > m) m = c;
    return m;
}

int count_bits(uint32_t x)
{
    int c = 0;
    while (x) {
        c += x & 1u;
        x >>= 1;
    }
    return c;
}
